package com.autoops.ai.service;import com.autoops.ai.dto.AIOperation;import com.autoops.ai.validation.AIOperationValidator;import org.springframework.stereotype.Service;import java.util.List;@Service public class AIStructuredOperationService{private final AIOperationValidator validator;public AIStructuredOperationService(AIOperationValidator v){validator=v;}public List<AIOperation> validate(List<AIOperation> operations){if(operations==null)return List.of();operations.forEach(validator::validate);return List.copyOf(operations);}}
